const originalStatusText=statusText;
statusText=function(value){return value==='submitted'?P().submitted:originalStatusText(value)};
async function api(path,options={}){const response=await fetch(path,{credentials:'same-origin',headers:{'content-type':'application/json',...(options.headers||{})},...options});const payload=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(payload.error||'REQUEST_FAILED');error.status=response.status;throw error}return payload}
async function runBusy(button,action){const label=button.innerHTML;button.disabled=true;button.setAttribute('aria-busy','true');button.textContent=Q().loading;try{return await action()}finally{if(document.contains(button)){button.disabled=false;button.removeAttribute('aria-busy');button.innerHTML=label}}}
function acceptServer(payload){platform.user=payload.user;platform.events=payload.events||[];platform.goals=payload.goals||[];platform.locations=payload.locations||[];platform.organizations=payload.organizations||[];platform.templates=payload.templates||[];platform.wasteTypes=payload.wasteTypes||[];platform.notifications=payload.notifications||[];state.role=payload.user?.role||state.role;state.reports=(payload.reports||[]).map(report=>({...report,kg:Number(report.kg),price:Number(report.price||0)}))}
function formatDate(value){if(!value)return '—';const date=new Date(value.length===10?`${value}T00:00:00`:value);const day=String(date.getDate()).padStart(2,'0'),month=String(date.getMonth()+1).padStart(2,'0'),year=date.getFullYear();return state.lang==='en'?`${day}/${month}/${year}`:`${day}.${month}.${year}`}
function money(value){return new Intl.NumberFormat(state.lang==='en'?'en-GB':state.lang==='ru'?'ru-RU':'kk-KZ',{style:'currency',currency:'KZT',maximumFractionDigits:0}).format(value||0)}
function safe(value){return escapeContent(value)}
function roleLabel(role){return role==='Operator'?P().operator:role==='Reviewer'?P().reviewer:role==='Leadership'?P().leadership:P().admin}
function reasonLabel(reason){return copy()[reason]||reason||copy().unknown}
const catalog={
  'Building B Canteen':['Б корпусының асханасы','Столовая корпуса Б','Building B Canteen'],'Coffee Point':['Кофехана','Кофейня','Coffee Point'],'ATU INN':['ATU INN','ATU INN','ATU INN'],'Food Technology Department':['Тағам технологиялары кафедрасы','Кафедра пищевых технологий','Food Technology Department'],'Meat & fish':['Ет және балық','Мясо и рыба','Meat & fish'],'Cooking oil':['Аспаздық май','Кулинарное масло','Cooking oil'],'Coffee grounds':['Кофе қалдығы','Кофейная гуща','Coffee grounds'],'Packaging':['Қаптама','Упаковка','Packaging'],'Canteen':['Асхана','Столовая','Canteen'],'Coffee shop':['Кофехана','Кофейня','Coffee shop'],'Hotel':['Қонақүй','Гостиница','Hotel'],'Department':['Кафедра','Кафедра','Department'],'Dormitory':['Жатақхана','Общежитие','Dormitory'],'Restaurant':['Мейрамхана','Ресторан','Restaurant'],'Daily kitchen form':['Күнделікті асхана формасы','Ежедневная форма столовой','Daily kitchen form'],'Coffee point form':['Кофехана формасы','Форма кофейни','Coffee point form'],'Hospitality form':['Қонақжайлық формасы','Форма гостиницы','Hospitality form'],'Monthly unit form':['Айлық бөлімше формасы','Месячная форма подразделения','Monthly unit form']};
function catalogLabel(value){return catalog[value]?.[state.lang==='kk'?0:state.lang==='ru'?1:2]||translateText(value)}
function notificationLabel(value){const entries={'Есеп қабылданды':['Есеп қабылданды','Отчёт принят','Report approved'],'Есеп түзетуге қайтарылды':['Есеп түзетуге қайтарылды','Отчёт возвращён на исправление','Report returned for correction'],'Жаңа есеп тексеруді күтуде':['Жаңа есеп тексеруді күтуде','Новый отчёт ожидает проверки','New report awaits review'],'Жаңа есеп жіберілді':['Жаңа есеп жіберілді','Новый отчёт отправлен','New report submitted'],'Түзетілген есеп қайта жіберілді':['Түзетілген есеп қайта жіберілді','Исправленный отчёт отправлен повторно','Corrected report resubmitted'],'Есеп тексеруге алынды':['Есеп тексеруге алынды','Отчёт взят на проверку','Report review started']};const direct=entries[value];if(direct)return direct[state.lang==='kk'?0:state.lang==='ru'?1:2];if(value.startsWith('Есеп мерзімі:')){const org=value.split(':').slice(1).join(':').trim();return state.lang==='kk'?`Есеп мерзімі: ${catalogLabel(org)}`:state.lang==='ru'?`Срок сдачи отчёта: ${catalogLabel(org)}`:`Report deadline: ${catalogLabel(org)}`}return value}
function optionLabel(value){if(['draft','submitted','review','returned','approved'].includes(value))return statusText(value);if(['over','portion','expired','prep','unknown'].includes(value))return reasonLabel(value);return catalogLabel(value)}
function eventLabel(action){const labels={created:{kk:'Құрылды',ru:'Создан',en:'Created'},updated:{kk:'Жаңартылды',ru:'Обновлён',en:'Updated'},submitted:{kk:'Жіберілді',ru:'Отправлен',en:'Submitted'},review:{kk:'Тексеруге алынды',ru:'Взят на проверку',en:'Review started'},resubmitted:{kk:'Қайта жіберілді',ru:'Отправлен повторно',en:'Resubmitted'},approved:{kk:'Қабылданды',ru:'Принят',en:'Approved'},returned:{kk:'Қайтарылды',ru:'Возвращён',en:'Returned'}};return labels[action]?.[state.lang]||statusText(action)||action}
function visibleReports(){return state.reports.filter(report=>{const f=platform.filters;const text=`${report.id} ${report.org} ${report.type} ${report.source} ${report.owner}`.toLowerCase();return(!f.query||text.includes(f.query.toLowerCase()))&&(!f.status||report.status===f.status)&&(!f.org||report.org===f.org)&&(!f.type||report.type===f.type)&&(!f.reason||report.reason===f.reason)&&(!f.from||report.date>=f.from)&&(!f.to||report.date<=f.to)})}
function optionList(values,current,label=P().all){return `<option value="">${label}</option>${values.filter(Boolean).filter((value,index,array)=>array.indexOf(value)===index).map(value=>`<option value="${safe(value)}" ${current===value?'selected':''}>${safe(optionLabel(value))}</option>`).join('')}`}
function reportRows(reports){return reports.map(report=>`<tr class="report-row" data-report="${safe(report.id)}" tabindex="0"><td><b>${safe(report.id)}</b></td><td>${safe(catalogLabel(report.org))}</td><td>${formatDate(report.date)}</td><td>${safe(catalogLabel(report.type))}</td><td>${report.kg.toFixed(1)} kg</td><td><span class="status ${report.status}">${statusText(report.status)}</span></td><td><button class="btn btn-soft btn-small" data-report="${safe(report.id)}">${P().details}</button></td></tr>`).join('')||`<tr><td colspan="7" class="empty">${P().noRecords}</td></tr>`}
function reportsTable(reports){return `<div class="table-scroll"><table class="data-table"><thead><tr><th>${L().id}</th><th>${L().org}</th><th>${L().date}</th><th>${L().category}</th><th>${L().amount}</th><th>${L().status}</th><th></th></tr></thead><tbody>${reportRows(reports)}</tbody></table></div>`}
function filterBar(){const f=platform.filters;return `<div class="filter-grid"><input id="filterQuery" value="${safe(f.query)}" placeholder="${Q().search}" aria-label="${Q().search}"><select id="filterStatus" aria-label="${L().status}">${optionList(['draft','submitted','review','returned','approved'],f.status)}</select><select id="filterOrg" aria-label="${L().org}">${optionList(state.reports.map(item=>item.org),f.org)}</select><select id="filterType" aria-label="${L().category}">${optionList(state.reports.map(item=>item.type),f.type)}</select><select id="filterReason" aria-label="${P().reason}">${optionList(['over','portion','expired','prep','unknown'],f.reason)}</select><label>${P().from}<input id="filterFrom" type="date" value="${f.from}"></label><label>${P().to}<input id="filterTo" type="date" value="${f.to}"></label><button class="btn btn-soft" id="clearFilters">${P().clear}</button></div>`}
function trendSvg(reports){const byDate={};reports.forEach(report=>byDate[report.date]=(byDate[report.date]||0)+report.kg);const points=Object.entries(byDate).sort(([a],[b])=>a.localeCompare(b)).slice(-8);if(!points.length)return `<div class="empty">${P().noRecords}</div>`;const max=Math.max(...points.map(([,value])=>value),1);const coords=points.map(([,value],index)=>`${20+index*(660/Math.max(points.length-1,1))},${210-(value/max)*170}`);return `<svg viewBox="0 0 700 240" role="img" aria-label="${L().trend}"><g stroke="#e7ecf3"><path d="M20 40H680M20 95H680M20 150H680M20 210H680"/></g><polyline points="${coords.join(' ')}" fill="none" stroke="#15966a" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>${coords.map(point=>{const[x,y]=point.split(',');return `<circle cx="${x}" cy="${y}" r="5" fill="#15966a"/>`}).join('')}</svg>`}
function dashboardReports(){const now=new Date(),year=now.getFullYear(),month=now.getMonth()+1,quarter=Math.floor((month-1)/3)+1;return state.reports.filter(item=>{const date=new Date(`${item.date}T00:00:00`);const period=platform.dashboardPeriod==='all'||(platform.dashboardPeriod==='year'&&date.getFullYear()===year)||(platform.dashboardPeriod==='month'&&date.getFullYear()===year&&date.getMonth()+1===month)||(platform.dashboardPeriod==='quarter'&&date.getFullYear()===year&&Math.floor(date.getMonth()/3)+1===quarter);return period&&(!platform.dashboardOrg||item.org===platform.dashboardOrg)})}
function dashboardV2(){const reports=dashboardReports();const approved=reports.filter(item=>item.status==='approved');const total=reports.reduce((sum,item)=>sum+item.kg,0);const approvedKg=approved.reduce((sum,item)=>sum+item.kg,0);const orgs=new Set(reports.map(item=>item.org)).size;const value=approved.reduce((sum,item)=>sum+item.kg*item.price,0);const pending=reports.filter(item=>['submitted','review'].includes(item.status));const canCreate=['Operator','Administrator'].includes(platform.user?.role);return `${intro(L().dashboard,L().dashSub,canCreate?`<button class="btn btn-primary" data-page="forms">＋ ${L().newReport}</button>`:'')}<div class="dashboard-control-row"><div class="server-indicator">● ${P().online} · ${P().actualData}</div><div class="dashboard-toolbar"><label>${Q().scope}<select id="dashboardPeriod"><option value="month" ${platform.dashboardPeriod==='month'?'selected':''}>${Q().month}</option><option value="quarter" ${platform.dashboardPeriod==='quarter'?'selected':''}>${Q().quarter}</option><option value="year" ${platform.dashboardPeriod==='year'?'selected':''}>${Q().year}</option><option value="all" ${platform.dashboardPeriod==='all'?'selected':''}>${Q().allTime}</option></select></label><label>${L().org}<select id="dashboardOrg">${optionList(state.reports.map(item=>item.org),platform.dashboardOrg,Q().allOrganizations)}</select></label></div></div><div class="stat-grid"><div class="stat-card"><div class="stat-top">${L().totalWaste}<span>◫</span></div><strong>${total.toFixed(1)} kg</strong><span class="muted">${reports.length} ${L().reports.toLowerCase()}</span></div><div class="stat-card"><div class="stat-top">${L().diverted}<span>↗</span></div><strong>${total?Math.round(approvedKg/total*100):0}%</strong><span class="muted">${approvedKg.toFixed(1)} kg</span></div><div class="stat-card"><div class="stat-top">${L().pending}<span>⌁</span></div><strong>${pending.length}</strong><span class="muted">${P().submitted} → ${L().review}</span></div><div class="stat-card"><div class="stat-top">${L().cost}<span>₸</span></div><strong>${money(value)}</strong><span class="muted">${L().approved}</span></div></div><div class="dashboard-grid"><section class="card"><div class="card-head"><h3>${L().trend}</h3><span class="status approved">${P().actualData}</span></div><div class="chart-wrap">${trendSvg(reports)}</div></section><section class="card"><div class="card-head"><h3>${L().orgs}</h3></div><div class="donut-layout"><div class="donut" style="background:conic-gradient(var(--green) 0 ${total?approvedKg/total*100:0}%,var(--yellow) 0)"><div class="donut-label"><strong>${orgs}</strong>${L().orgs}</div></div><div class="donut-legend"><span><i class="dot" style="background:#15966a"></i>${L().approved}: ${approved.length}</span><span><i class="dot" style="background:#2563eb"></i>${P().submitted}: ${reports.filter(item=>item.status==='submitted').length}</span><span><i class="dot" style="background:#ffd51c"></i>${L().review}: ${reports.filter(item=>item.status==='review').length}</span><span><i class="dot" style="background:#d92d20"></i>${L().returned}: ${reports.filter(item=>item.status==='returned').length}</span></div></div></section></div><section class="card table-card"><div class="card-head"><h3>${L().recent}</h3><button class="btn btn-soft" data-page="submissions">${L().submissions} →</button></div>${reportsTable(reports.slice(0,5))}</section>`}
function formV2(){const report=platform.editId&&state.reports.find(item=>item.id===platform.editId);const allowed=platform.user&&['Operator','Administrator'].includes(platform.user.role);if(!allowed)return `${intro(L().forms,L().formSub)}<div class="card empty">${P().roleDenied}</div>`;const today=new Date().toISOString().slice(0,10),month=today.slice(0,7);const organizations=platform.user.role==='Operator'?platform.organizations.filter(item=>item.name===platform.user.org):platform.organizations;const selectedOrg=report?.org||platform.formOrg||organizations[0]?.name||platform.user.org;const org=platform.organizations.find(item=>item.name===selectedOrg);const template=platform.templates.find(item=>item.id===org?.template)||platform.templates[0];const sources=platform.locations.filter(item=>item.org===selectedOrg).map(item=>item.name);if(!sources.length)sources.push(`${selectedOrg} collection point`);const types=template?.types||platform.wasteTypes.map(item=>item.name);const orgReports=state.reports.filter(item=>item.org===selectedOrg);const todayKg=orgReports.filter(item=>item.date===today).reduce((sum,item)=>sum+item.kg,0),monthKg=orgReports.filter(item=>item.date.startsWith(month)).reduce((sum,item)=>sum+item.kg,0);const value=(key,fallback='')=>safe(report?.[key]??fallback);return `${intro(report?P().edit:L().forms,report?`${report.id} · ${statusText(report.status)}`:L().formSub)}<div class="form-summary"><article class="stat-card"><small>${P().todaySummary}</small><strong>${todayKg.toFixed(1)} kg</strong><span>${catalogLabel(selectedOrg)}</span></article><article class="stat-card"><small>${P().monthSummary}</small><strong>${monthKg.toFixed(1)} kg</strong><span>${month}</span></article><article class="stat-card template-card"><small>${P().template}</small><strong>${safe(catalogLabel(template?.name||'—'))}</strong><span>${P().frequency}: ${template?.frequency==='daily'?P().daily:P().monthly}</span></article></div><form class="card" id="platformForm"><div class="validation-note">✓ ${P().validated}: 0.1–10 000 kg</div><div class="form-grid"><div class="field"><label>${L().org}</label><select id="platformOrg" name="org" required ${platform.user.role==='Operator'?'disabled':''}>${optionList(organizations.map(item=>item.name),selectedOrg,'')}</select>${platform.user.role==='Operator'?`<input type="hidden" name="org" value="${safe(selectedOrg)}">`:''}</div><div class="field"><label>${L().date}</label><input name="date" type="date" max="${today}" value="${value('date',today)}" required></div><div class="field"><label>${P().collection}</label><select name="source" required>${optionList(sources,report?.source,'')}</select></div><div class="field"><label>${L().category}</label><select name="type" required>${optionList(types,report?.type,'')}</select></div><div class="field"><label>${L().weight}</label><input name="kg" type="number" min="0.1" max="10000" step="0.1" value="${value('kg')}" required></div><div class="field"><label>${P().reason}</label><select name="reason" required>${optionList(['over','portion','expired','prep','unknown'],report?.reason,'')}</select></div><div class="field"><label>${copy().price}</label><input name="price" type="number" min="0" max="10000000" step="1" value="${value('price',0)}" required></div><div class="field span-2"><label>${L().notes}</label><textarea name="notes">${value('notes')}</textarea></div><div class="field span-2"><label>${P().photoEvidence}</label><input id="platformPhoto" type="file" accept="image/*" capture="environment"><img id="platformPhotoPreview" class="evidence-preview" src="${value('photo')}" alt="${P().photoEvidence}" ${report?.photo?'':'hidden'}></div></div>${report?.reviewComment?`<div class="return-comment"><strong>${L().comment}</strong><p>${safe(report.reviewComment)}</p></div>`:''}<div class="form-actions"><button type="button" class="btn btn-soft" data-save-status="draft">${L().saveDraft}</button><button class="btn btn-green" data-save-status="submitted">${report?P().resubmit:L().submit}</button></div></form>`}
function detailsV2(report){if(!report)return '';const history=platform.events.filter(item=>item.reportId===report.id).sort((a,b)=>b.time.localeCompare(a.time));const canStart=['Reviewer','Administrator'].includes(platform.user?.role)&&report.status==='submitted';const canReview=['Reviewer','Administrator'].includes(platform.user?.role)&&report.status==='review';const canEdit=['draft','returned'].includes(report.status)&&(platform.user?.role==='Administrator'||report.owner===platform.user?.email);return `<aside class="card report-detail"><div class="card-head"><div><h3>${safe(report.id)}</h3><span class="status ${report.status}">${statusText(report.status)}</span></div><button class="icon-btn" id="closeDetail" aria-label="Close">×</button></div><div class="workflow-strip"><span class="done">${L().draft}</span><span class="${['submitted','review','approved','returned'].includes(report.status)?'done':''}">${P().submitted}</span><span class="${['review','approved','returned'].includes(report.status)?'done':''}">${L().review}</span><span class="${['approved','returned'].includes(report.status)?'done':''}">${report.status==='returned'?L().returned:L().approved}</span></div><dl class="detail-list"><div><dt>${L().org}</dt><dd>${safe(catalogLabel(report.org))}</dd></div><div><dt>${P().createdBy}</dt><dd>${safe(report.owner)}</dd></div><div><dt>${L().date}</dt><dd>${formatDate(report.date)}</dd></div><div><dt>${L().category}</dt><dd>${safe(catalogLabel(report.type))}</dd></div><div><dt>${L().amount}</dt><dd>${report.kg.toFixed(1)} kg</dd></div><div><dt>${P().reason}</dt><dd>${safe(reasonLabel(report.reason))}</dd></div><div><dt>${P().collection}</dt><dd>${safe(catalogLabel(report.source))}</dd></div><div><dt>${P().value}</dt><dd>${money(report.kg*report.price)}</dd></div></dl><div class="evidence-block"><h4>${P().photoEvidence}</h4>${report.photo?`<img src="${safe(report.photo)}" alt="${P().photoEvidence}">`:`<p class="muted">${P().noPhoto}</p>`}</div>${report.reviewComment?`<div class="return-comment"><strong>${L().comment}</strong><p>${safe(report.reviewComment)}</p></div>`:''}<h4>${P().history}</h4><div class="timeline">${history.map(item=>`<div class="timeline-item"><span class="timeline-dot"></span><div><strong>${safe(eventLabel(item.action))}</strong><p>${safe(item.actor)} · ${formatDate(item.time)}${item.comment?`<br>${safe(item.comment)}`:''}</p></div></div>`).join('')||`<p class="muted">${copy().empty}</p>`}</div>${canStart?`<button class="btn btn-blue full" data-review="startReview">${P().startReview}</button>`:''}${canReview?`<div class="field"><label>${L().comment}</label><textarea id="reviewComment"></textarea></div><div class="form-actions"><button class="btn btn-danger" data-review="return">${L().sendBack}</button><button class="btn btn-green" data-review="approve">${L().accept}</button></div>`:''}${canEdit?`<button class="btn btn-blue full" data-edit="${safe(report.id)}">${P().edit}</button>`:''}</aside>`}
function submissionsV2(){const reports=visibleReports();const selected=state.reports.find(item=>item.id===platform.selectedId);const title=platform.user?.role==='Operator'?P().myReports:platform.user?.role==='Reviewer'?P().reviewQueue:P().allReports;return `${intro(L().submissions,title)}${filterBar()}<div class="review-panel"><section class="card table-card">${reportsTable(reports)}</section>${selected?detailsV2(selected):`<aside class="card empty">${P().details}</aside>`}</div>`}
function periodReports(){const now=new Date(),year=now.getFullYear(),month=now.getMonth()+1,quarter=Math.floor((month-1)/3)+1;return visibleReports().filter(item=>{const date=new Date(`${item.date}T00:00:00`);const match=platform.reportPeriod==='all'||(platform.reportPeriod==='year'&&date.getFullYear()===year)||(platform.reportPeriod==='month'&&date.getFullYear()===year&&date.getMonth()+1===month)||(platform.reportPeriod==='quarter'&&date.getFullYear()===year&&Math.floor(date.getMonth()/3)+1===quarter);return match&&(!platform.acceptedOnly||item.status==='approved')})}
function reportsV2(){const reports=periodReports();const month=new Date().toISOString().slice(0,7);const submitted=new Set(state.reports.filter(item=>item.date.startsWith(month)&&item.status!=='draft').map(item=>item.org));const missing=platform.organizations.filter(item=>!submitted.has(item.name));const canRemind=['Reviewer','Administrator'].includes(platform.user?.role);return `${intro(L().reports,P().registry)}<div class="period-toolbar"><label>${P().period}<select id="reportPeriod"><option value="month" ${platform.reportPeriod==='month'?'selected':''}>${P().monthly}</option><option value="quarter" ${platform.reportPeriod==='quarter'?'selected':''}>${P().quarter}</option><option value="year" ${platform.reportPeriod==='year'?'selected':''}>${P().year}</option><option value="all" ${platform.reportPeriod==='all'?'selected':''}>${P().allPeriods}</option></select></label><label class="check-line"><input id="acceptedOnly" type="checkbox" ${platform.acceptedOnly?'checked':''}> ${P().acceptedOnly}</label></div>${filterBar()}<div class="report-actions"><article class="action-card"><div class="feature-icon">X</div><h3>${L().excel}</h3><p>${P().visibleData}: ${reports.length}</p><button class="btn btn-green" id="exportFiltered">⇩ ${L().download}</button></article><article class="action-card"><div class="feature-icon">PDF</div><h3>${L().pdf}</h3><p>${P().visibleData}: ${reports.reduce((sum,item)=>sum+item.kg,0).toFixed(1)} kg</p><button class="btn btn-blue" id="printFiltered">⇩ ${L().download}</button></article><article class="action-card"><div class="feature-icon">◫</div><h3>${P().registry}</h3><p>${reports.length} · ${money(reports.reduce((sum,item)=>sum+item.kg*item.price,0))}</p></article></div><section class="card table-card" id="printArea">${reportsTable(reports)}</section><section class="card missing-card"><div class="card-head"><div><h3>${P().missingReports}</h3><p class="muted">${month} · ${missing.length}</p></div>${canRemind&&missing.length?`<button class="btn btn-warning" id="sendReminders">♢ ${P().sendReminders}</button>`:''}</div><div class="missing-list">${missing.map(item=>`<span>${safe(catalogLabel(item.name))}<small>${item.responsible}</small></span>`).join('')||`<p class="muted">✓ ${P().noRecords}</p>`}</div></section>`}
function metricBars(items){const max=Math.max(...items.map(item=>item.value),1);return `<div class="metric-bars">${items.map(item=>`<div class="metric-row"><div><span>${safe(catalogLabel(item.label))}</span><strong>${item.value.toFixed(1)} kg</strong></div><i><b style="width:${item.value?Math.max(3,item.value/max*100):0}%"></b></i></div>`).join('')||`<p class="muted">${P().noRecords}</p>`}</div>`}
function analyticsV2(){const approved=state.reports.filter(item=>item.status==='approved');const kg=approved.reduce((sum,item)=>sum+item.kg,0);const co2=approved.reduce((sum,item)=>sum+item.kg*(platform.wasteTypes.find(type=>type.name===item.type)?.co2||2.5),0),water=kg*.16;const recyclable=approved.filter(item=>platform.wasteTypes.find(type=>type.name===item.type)?.recyclable).reduce((sum,item)=>sum+item.kg,0);const group=key=>Object.entries(approved.reduce((acc,item)=>{acc[item[key]]=(acc[item[key]]||0)+item.kg;return acc},{})).map(([label,total])=>({label,value:total})).sort((a,b)=>b.value-a.value);const typeGroups=group('type'),orgGroups=group('org');const monthlyGroups=Array.from({length:6},(_,offset)=>{const date=new Date();date.setDate(1);date.setMonth(date.getMonth()-(5-offset));const label=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;return{label,value:approved.filter(item=>item.date.startsWith(label)).reduce((sum,item)=>sum+item.kg,0)}});const average=approved.length?kg/approved.length:0;const anomalies=approved.filter(item=>item.kg>average*1.5);const language=state.lang,waterLabel=language==='kk'?'Су':language==='ru'?'Вода':'Water';const formulas=language==='kk'?['CO₂e = Σ(кг × коэффициент)','Су = кг × 160 л','Құн = кг × ₸/кг']:language==='ru'?['CO₂e = Σ(кг × коэффициент)','Вода = кг × 160 л','Стоимость = кг × ₸/кг']:['CO₂e = Σ(kg × factor)','Water = kg × 160 L','Value = kg × ₸/kg'];return `${intro(L().analytics,L().analyticsSub)}<div class="esg-grid"><div class="esg-card green"><small>${L().co2}</small><strong>${co2.toFixed(1)} kg</strong><span>CO₂e</span></div><div class="esg-card blue"><small>${L().water}</small><strong>${water.toFixed(1)} m³</strong><span>${waterLabel}</span></div><div class="esg-card gold"><small>${P().recyclableShare}</small><strong>${kg?Math.round(recyclable/kg*100):0}%</strong><span>${recyclable.toFixed(1)} kg</span></div></div><div class="analytics-grid"><section class="card"><h3>${P().structure}</h3>${metricBars(typeGroups)}</section><section class="card"><h3>${P().comparison}</h3>${metricBars(orgGroups)}</section><section class="card analytics-wide"><h3>${Q().periodComparison}</h3>${metricBars(monthlyGroups)}</section></div><section class="card anomaly-card"><div class="card-head"><h3>${P().anomalies}</h3><span class="status ${anomalies.length?'returned':'approved'}">${anomalies.length}</span></div>${anomalies.length?anomalies.map(item=>`<div class="setting-row"><span>${safe(item.id)} · ${safe(catalogLabel(item.org))}</span><strong>${item.kg.toFixed(1)} kg</strong></div>`).join(''):`<p class="muted">✓ ${P().noAnomalies}</p>`}</section><section class="card method-card"><div class="card-head"><h3>${P().method}</h3><span class="status review">MVP</span></div><p>${P().methodText}</p><div class="formula-grid">${formulas.map(formula=>`<code>${formula}</code>`).join('')}</div></section><section class="card"><div class="card-head"><h3>${L().trend}</h3><span class="status approved">${P().actualData}</span></div><div class="chart-wrap">${trendSvg(approved)}</div></section>`}
function impactV2(){const orgs=[...new Set(state.reports.map(item=>item.org))];const goal=platform.goals[0]||{org:orgs[0]||'Main Canteen',baseline:10,current:10,target:10};const progress=impactModel.progress(Number(goal.baseline),Number(goal.current),Number(goal.target));const editable=['Reviewer','Administrator'].includes(platform.user?.role);return `${intro(copy().title,copy().sub)}<div class="settings-grid impact-grid"><section class="card"><h3>${P().goal}</h3><form id="platformGoal"><div class="field"><label>${L().org}</label><select name="org" ${editable?'':'disabled'}>${optionList(orgs,goal.org,'')}</select></div>${numberField('baseline',P().baseline,goal.baseline,.001)}${numberField('current',P().current,goal.current,0)}${numberField('target',P().target,goal.target,.001,100)}<progress value="${progress.progress}" max="100"></progress><p>${copy().change}: <strong>${progress.reduction.toFixed(1)}%</strong></p>${editable?`<button class="btn btn-blue">${P().saveGoal}</button>`:''}</form></section><section class="card"><h3>${copy().advice}</h3>${['over','portion','expired','prep'].map(reason=>{const total=state.reports.filter(item=>item.status==='approved'&&item.reason===reason).reduce((sum,item)=>sum+item.kg,0);return `<div class="setting-row"><span>${copy()[reason]}</span><strong>${total.toFixed(1)} kg</strong></div>`}).join('')}</section></div>`}
function qrPage(){const base=location.origin+location.pathname;return `${intro(L().mobile,P().locationQr)}<p class="section-sub">${P().qrHelp}</p><div class="qr-grid">${platform.locations.map(location=>{const target=`${base}?location=${encodeURIComponent(location.id)}`;const image=`https://quickchart.io/qr?text=${encodeURIComponent(target)}&size=220&margin=2&dark=06347e&light=ffffff&ecLevel=Q`;return `<article class="card qr-card"><img src="${image}" alt="QR ${safe(location.id)}"><h3>${safe(translateText(location.name))}</h3><p>${safe(translateText(location.org))} · ${safe(location.id)}</p><div class="form-actions"><a class="btn btn-blue" href="${target}">${P().openForm}</a><button class="btn btn-soft" data-copy="${safe(target)}">${P().copyLink}</button></div></article>`}).join('')}</div>`}
function notificationsV2(){return `${intro(L().notifications,L().notifSub,`<button class="btn btn-soft" id="readNotifications">✓ ${P().readAll}</button>`)}<div class="notification-list">${platform.notifications.length?platform.notifications.map(item=>`<article class="notification ${item.read?'':'unread'}" data-notification-report="${safe(item.reportId||'')}"><div class="feature-icon">♢</div><div><h4>${safe(notificationLabel(item.title))}</h4><p>${safe(item.reportId||'')}</p></div><time>${formatDate(item.time)}</time></article>`).join(''):`<div class="card empty">${P().notificationsEmpty}</div>`}</div>`}
function settingsV2(){return `${intro(L().settings,L().settingsSub)}<div class="settings-grid"><section class="card"><div class="card-head"><h3>${L().profileSettings}</h3><span class="status approved">${P().server}</span></div><div class="setting-row"><span>${L().email}</span><strong>${safe(platform.user?.email)}</strong></div><div class="setting-row"><span>${P().roles}</span><strong>${roleLabel(platform.user?.role)}</strong></div><div class="setting-row"><span>${L().org}</span><strong>${safe(catalogLabel(platform.user?.org))}</strong></div></section><section class="card"><h3>${P().accounts}</h3><p><code>operator@atu.kz</code> · ${P().operator}</p><p><code>reviewer@atu.kz</code> · ${P().reviewer}</p><p><code>admin@atu.kz</code> · ${P().admin}</p><p><code>leadership@atu.kz</code> · ${P().leadership}</p><p class="demo-note">${P().passwordHint}</p></section></div>`}
function organizationsV2(){if(!['Reviewer','Administrator','Leadership'].includes(platform.user?.role))return `${intro(L().organizations,L().orgSub)}<div class="card empty">${P().roleDenied}</div>`;return `${intro(L().organizations,L().orgSub)}<div class="org-grid">${platform.organizations.map(org=>{const template=platform.templates.find(item=>item.id===org.template);return `<article class="org-card registry-card"><div class="org-mark">${safe(org.id)}</div><h3>${safe(catalogLabel(org.name))}</h3><p>${P().kind}: <strong>${safe(catalogLabel(org.kind))}</strong></p><p>${P().template}: <strong>${safe(catalogLabel(template?.name||'—'))}</strong></p><p>${P().responsible}: <strong>${safe(org.responsible)}</strong></p><p>${P().deadline}: <strong>${org.deadlineDay}</strong></p><div class="role-pills"><span>${P().operator}</span><span>${P().reviewer}</span><span>${P().admin}</span><span>${P().leadership}</span></div></article>`}).join('')}</div>`}

const baseLandingV2=landing;
landing=function(){return baseLandingV2().replace(`<strong>3</strong>${campus().roles}`,`<strong>4</strong>${campus().roles}`)};
const baseLogin=login;
function serverDemoNote(){return state.lang==='kk'?'Демо аккаунттар сервердегі тұрақты деректермен жұмыс істейді.':state.lang==='ru'?'Демо-аккаунты работают с данными, сохранёнными на сервере.':'Demo accounts use data persisted on the server.'}
login=function(){return baseLogin().replace(L().demoNote,serverDemoNote()).replace('</form>',`<div class="account-hints"><strong>${P().accounts}</strong><button type="button" data-demo-email="operator@atu.kz">${P().operator}</button><button type="button" data-demo-email="reviewer@atu.kz">${P().reviewer}</button><button type="button" data-demo-email="admin@atu.kz">${P().admin}</button><button type="button" data-demo-email="leadership@atu.kz">${P().leadership}</button><small>${P().passwordHint}</small></div></form>`)};
navItems=function(){if(!platform.user)return '';const role=platform.user.role;const pages=role==='Operator'?['dashboard','forms','mobile','submissions','reports','analytics','impact']:role==='Reviewer'?['dashboard','submissions','organizations','reports','analytics','impact']:role==='Leadership'?['dashboard','organizations','reports','analytics','impact']:['dashboard','forms','mobile','submissions','organizations','reports','analytics','impact'];return pages.map(page=>`<button class="nav-item ${state.page===page?'active':''}" data-page="${page}"><span class="nav-icon">${icons[page]||'↘'}</span>${L()[page]||P()[page]||copy().title}</button>`).join('')}
pageContent=function(){return ({dashboard:dashboardV2,forms:formV2,mobile:qrPage,submissions:submissionsV2,organizations:organizationsV2,reports:reportsV2,analytics:analyticsV2,impact:impactV2,notifications:notificationsV2,settings:settingsV2}[state.page]||dashboardV2)()}
function syncFilters(){const mapping={filterQuery:'query',filterStatus:'status',filterOrg:'org',filterType:'type',filterReason:'reason',filterFrom:'from',filterTo:'to'};Object.entries(mapping).forEach(([id,key])=>{const element=document.getElementById(id);if(element)element.oninput=element.onchange=()=>{platform.filters[key]=element.value;render()}});const clear=document.getElementById('clearFilters');if(clear)clear.onclick=()=>{Object.keys(platform.filters).forEach(key=>platform.filters[key]='');render()}}
function bindPlatform(){
  document.querySelectorAll('[data-demo-email]').forEach(button=>button.onclick=()=>{const form=document.getElementById('loginForm');form.email.value=button.dataset.demoEmail;form.password.value='demo2026'});
  const loginNote=document.querySelector('#loginForm .demo-note');if(loginNote)loginNote.textContent=`ⓘ ${serverDemoNote()}`;const passwordNote=document.querySelector('#loginForm .account-hints small');if(passwordNote)passwordNote.textContent=P().passwordHint;
  const loginForm=document.getElementById('loginForm');if(loginForm)loginForm.onsubmit=async event=>{event.preventDefault();if(!loginForm.reportValidity())return;try{const payload=await api('/api/login',{method:'POST',body:JSON.stringify({email:loginForm.email.value,password:loginForm.password.value})});acceptServer(payload);state.view='app';state.page='dashboard';render()}catch(error){toast(error.status===401?P().invalidLogin:P().serverError)}};
  document.querySelectorAll('[data-action="logout"]').forEach(button=>button.onclick=async()=>{await api('/api/logout',{method:'POST',body:'{}'}).catch(()=>{});platform.user=null;state.view='landing';render();toast(P().loggedOut)});
  document.querySelectorAll('.profile').forEach(profile=>{if(platform.user)profile.innerHTML=`<div class="avatar">${safe(platform.user.name.split(' ').map(item=>item[0]).join('').slice(0,2))}</div><div><strong>${safe(platform.user.name)}</strong><small>${roleLabel(platform.user.role)}</small></div>`});
  document.querySelectorAll('.demo-chip').forEach(item=>item.textContent=P().server);
  syncFilters();
  const orgSelect=document.getElementById('platformOrg');if(orgSelect)orgSelect.onchange=()=>{platform.formOrg=orgSelect.value;render()};
  const reportPeriod=document.getElementById('reportPeriod');if(reportPeriod)reportPeriod.onchange=()=>{platform.reportPeriod=reportPeriod.value;render()};
  const acceptedOnly=document.getElementById('acceptedOnly');if(acceptedOnly)acceptedOnly.onchange=()=>{platform.acceptedOnly=acceptedOnly.checked;render()};
  const dashboardPeriod=document.getElementById('dashboardPeriod');if(dashboardPeriod)dashboardPeriod.onchange=()=>{platform.dashboardPeriod=dashboardPeriod.value;render()};
  const dashboardOrg=document.getElementById('dashboardOrg');if(dashboardOrg)dashboardOrg.onchange=()=>{platform.dashboardOrg=dashboardOrg.value;render()};
  document.querySelectorAll('[data-report]').forEach(element=>element.onclick=()=>{platform.selectedId=element.dataset.report;state.page='submissions';render()});
  const close=document.getElementById('closeDetail');if(close){close.setAttribute('aria-label',Q().close);close.onclick=()=>{platform.selectedId=null;render()}};
  document.querySelectorAll('[data-edit]').forEach(button=>button.onclick=()=>{platform.editId=button.dataset.edit;state.page='forms';render()});
  const photo=document.getElementById('platformPhoto');if(photo)photo.onchange=()=>{const file=photo.files[0];if(!file)return;if(file.size>1_500_000){toast(photoLimitMessage());photo.value='';return}const reader=new FileReader();reader.onload=()=>{platform.photoData=reader.result;const preview=document.getElementById('platformPhotoPreview');preview.src=reader.result;preview.hidden=false};reader.readAsDataURL(file)};
  const form=document.getElementById('platformForm');if(form)form.querySelectorAll('[data-save-status]').forEach(button=>button.onclick=async event=>{event.preventDefault();if(!form.reportValidity()){toast(P().formError);return}const input=Object.fromEntries(new FormData(form));input.kg=Number(input.kg);input.price=Number(input.price);input.status=button.dataset.saveStatus;input.photo=platform.photoData||state.reports.find(item=>item.id===platform.editId)?.photo||'';await runBusy(button,async()=>{try{const payload=platform.editId?await api(`/api/reports/${encodeURIComponent(platform.editId)}`,{method:'PATCH',body:JSON.stringify(input)}):await api('/api/reports',{method:'POST',body:JSON.stringify(input)});acceptServer(payload);platform.editId=null;platform.photoData='';state.page='submissions';platform.selectedId=state.reports[0]?.id;render()}catch{toast(P().serverError)}})});
  document.querySelectorAll('[data-review]').forEach(button=>button.onclick=async()=>{const comment=document.getElementById('reviewComment')?.value.trim()||'';if(button.dataset.review==='return'&&!comment){toast(state.lang==='kk'?'Қайтару себебін жазыңыз':state.lang==='ru'?'Укажите причину возврата':'Enter a return reason');return}await runBusy(button,async()=>{try{const payload=await api(`/api/reports/${encodeURIComponent(platform.selectedId)}`,{method:'PATCH',body:JSON.stringify({action:button.dataset.review,comment})});acceptServer(payload);render()}catch{toast(P().serverError)}})});
  const exportButton=document.getElementById('exportFiltered');if(exportButton)exportButton.onclick=()=>{const reports=periodReports();const html=`<html><meta charset="utf-8"><table><tr>${['ID',L().org,L().date,L().category,L().amount,P().reason,L().status].map(item=>`<th>${item}</th>`).join('')}</tr>${reports.map(item=>`<tr><td>${safe(item.id)}</td><td>${safe(catalogLabel(item.org))}</td><td>${safe(item.date)}</td><td>${safe(catalogLabel(item.type))}</td><td>${item.kg}</td><td>${safe(reasonLabel(item.reason))}</td><td>${safe(statusText(item.status))}</td></tr>`).join('')}</table></html>`;const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([html],{type:'application/vnd.ms-excel'}));link.download=`ecofood-${platform.reportPeriod}-${new Date().toISOString().slice(0,10)}.xls`;link.click();URL.revokeObjectURL(link.href);toast(P().exported)};
  const printArea=document.getElementById('printArea');if(printArea){const records=periodReports();printArea.insertAdjacentHTML('afterbegin',`<div class="print-header"><h1>${Q().printTitle}</h1><p>${Q().printNote} · ${formatDate(new Date().toISOString())} · ${records.length} ${L().reports.toLowerCase()} · ${records.reduce((sum,item)=>sum+item.kg,0).toFixed(1)} kg</p></div>`)}
  const printButton=document.getElementById('printFiltered');if(printButton)printButton.onclick=()=>{const previousTitle=document.title;document.title=Q().printTitle;document.body.classList.add('printing');window.onafterprint=()=>{document.body.classList.remove('printing');document.title=previousTitle;window.onafterprint=null};window.print()};
  document.querySelectorAll('[data-copy]').forEach(button=>button.onclick=async()=>{await navigator.clipboard.writeText(button.dataset.copy);toast(P().copied)});
  const goalForm=document.getElementById('platformGoal');if(goalForm)goalForm.onsubmit=async event=>{event.preventDefault();const input=Object.fromEntries(new FormData(goalForm));['baseline','current','target'].forEach(key=>input[key]=Number(input[key]));try{const payload=await api('/api/goals',{method:'POST',body:JSON.stringify(input)});acceptServer(payload);render()}catch{toast(P().serverError)}};
  const read=document.getElementById('readNotifications');if(read)read.onclick=async()=>{const payload=await api('/api/notifications/read',{method:'POST',body:'{}'});acceptServer(payload);render()};
  const reminders=document.getElementById('sendReminders');if(reminders)reminders.onclick=async()=>runBusy(reminders,async()=>{try{const payload=await api('/api/reminders/run',{method:'POST',body:'{}'});acceptServer(payload);toast(P().remindersSent);render()}catch{toast(P().serverError)}});
  document.querySelectorAll('[data-notification-report]').forEach(item=>item.onclick=()=>{if(item.dataset.notificationReport){platform.selectedId=item.dataset.notificationReport;state.page='submissions';render()}});
  const params=new URLSearchParams(location.search);const locationId=params.get('location');if(locationId&&platform.user&&state.view==='app'){const locationItem=platform.locations.find(item=>item.id===locationId);if(locationItem){state.page='forms';history.replaceState({},'',location.pathname);setTimeout(()=>{const form=document.getElementById('platformForm');if(form){form.org.value=locationItem.org;form.source.value=locationItem.name}},0)}}
}
const priorRender=render;
render=function(){priorRender();bindPlatform()};
api('/api/state').then(payload=>{acceptServer(payload);state.view='app';render()}).catch(()=>render());
